import {defaults,zones,workshop,jobState,energyDay,parseReadings} from './twin-model.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const meta={
 winger:{title:'Winger Penrose. A day in the workshop.',chapter:'01 / AUTOMOTIVE · SPATIAL OPERATIONS',intro:'Follow a vehicle through inspection, service and handover.',prompt:'What happens when a service bay is unavailable?',experiment:'Take one bay offline',story:'Every wait has a place. And a next move.',copy:'A customer sees their next step. A service adviser sees the hold-up. A workshop manager sees the queue. The same spatial model can tell each person the part of the story they need.',link:'https://winger.co.nz/locations/customer-service-centre/',note:'Conceptual Penrose layout · not the actual floor plan. All vehicles, bay counts and timings are synthetic. No workshop system is connected.',next:'A draft customer update with the current stage, the reason for a hold and the next check. A service adviser confirms it before anything is sent.'},
 home:{title:'Your home. Energy you can see.',chapter:'02 / CONSUMER · HOME ENERGY',intro:'Follow energy from the roof to the rooms, battery and car.',prompt:'Could flexible loads use more of the midday solar?',experiment:'Try a solar-friendly day',story:'An electricity bill becomes a place you recognise.',copy:'Touch the kitchen, the heat pump or the EV. See how timing changes grid demand. A useful consumer experience connects an understandable house to the meter, the appliances and the choices the household actually controls.',link:'https://contact.co.nz/support/electricity-and-meters/solar',note:'Illustrative home and hourly energy model. Values are assumptions, not meter readings, a system design or a savings forecast.',next:'A suggested EV and hot-water schedule with the household’s constraints attached. The homeowner reviews it before an installer or a future authorised controller changes anything.'},
 school:{title:'A school that makes its energy visible.',chapter:'03 / SCHOOLS & BUILDINGS · ROOM-LEVEL INSIGHT',intro:'Explore learning blocks, shared spaces and essential loads.',prompt:'What keeps using electricity when the school is empty?',experiment:'Explore a holiday day',story:'One building. Many rooms. Clearer decisions.',copy:'A caretaker can inspect after-hours loads. A principal can understand an energy project. Students can explore how their school works. A future sensor layer can connect each room to power, occupancy, temperature and air-quality readings.',link:'https://www.education.govt.nz/our-work/strategies-policies-and-programmes/property-and-infrastructure/te-haratau/energy-survey-schools',note:'Invented school plan and sample electrical loads. Essential services remain on. Comfort, air quality and safe ventilation are not modelled.',next:'A review of non-essential after-hours loads, with a room list and unresolved comfort requirements. A property manager verifies the recommendation.'},
 grocery:{title:'A grocery store, from chiller to collection.',chapter:'04 / GROCERY · STORE & HOUSEHOLD',intro:'See the always-on cold chain alongside the store’s working day.',prompt:'What is still running after the shoppers go home?',experiment:'Explore a quiet day',story:'See the store. Then see the shop become dinner.',copy:'Refrigeration, preparation and collection make grocery a strong spatial use case. Pair the store view with The Kitchen Machine: a household can inspect food, rehearse the week and prepare a shopping list with human review.',link:'index.html',note:'Generic store layout and sample power values. Refrigeration stays on in every scenario. No product stock, food temperatures or retailer readings are connected.',next:'An exception list for the store team: which zones need a meter check and which loads could follow trading hours. Refrigeration and food safety require separate verified controls.'},
 retail:{title:'Retail, with the back of house in view.',chapter:'05 / RETAIL · SPACE, SERVICE & ENERGY',intro:'Connect the showroom to stock, collections and team spaces.',prompt:'What if unused areas followed an occupancy schedule?',experiment:'Try an empty-building day',story:'The customer sees the product. The team sees the system.',copy:'A customer can explore fit, assembly and use. The operator can inspect the stockroom, collection area and energy load. Begin with one decision: a product assembly, a collection bottleneck or an after-hours energy review.',link:'https://www.mitre10.co.nz/guides-and-advice/',note:'Generic retail example. Layout, occupancy and power values are invented. No retailer stock or transaction system is connected.',next:'A draft operating schedule for non-essential lighting and equipment, with the affected areas named. The store manager checks security and operating requirements.'}
};
let kind=Object.hasOwn(meta,location.hash.slice(1))?location.hash.slice(1):'winger',options=structuredClone(defaults),minute=120,hour=12,selected=zones[kind][0][0],scene=null,playing=null,showComparison=false,readings=null,planURL=null,roof=false,labels=true;
const fmt=n=>(Math.round(n*10)/10).toFixed(1),clock=m=>String(8+Math.floor(m/60)).padStart(2,'0')+':'+String(Math.round(m%60)).padStart(2,'0'),hclock=h=>String(h).padStart(2,'0')+':00';
function notice(t){$('#notice').textContent=t;$('#notice').classList.add('show');clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('#notice').classList.remove('show'),4000);}
function range(id,label,min,max,step,suffix=''){return `<label class="parameter"><span>${label}<output id="out-${id}">${options[kind][id]}${suffix}</output></span><input data-option="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${options[kind][id]}" aria-label="${label}"></label>`;}
function toggle(id,label){return `<label class="switch"><input type="checkbox" data-option="${id}" ${options[kind][id]?'checked':''}><span>${label}</span></label>`;}
function buildControls(){
 $('#parameters').innerHTML=kind==='winger'?range('bays','Available service bays',1,3,1)+range('approval','Approval wait',0,60,5,' min')+range('parts','Extra parts delay',0,90,15,' min')+toggle('rush','Add three extra bookings'):
 range('solar','Solar capacity',0,kind==='home'?12:40,1,' kW')+(kind==='home'?range('battery','Usable battery capacity',0,20,1,' kWh'):'')+range('cloud','Sunlight factor',.2,1,.1)+toggle('occupied',kind==='school'?'School day / occupied':kind==='home'?'Household at home':'Busy trading day')+toggle('smart',kind==='home'?'Shift EV + hot water to midday':'Zone non-essential after-hours loads');
 $('#parameters').oninput=e=>{const t=e.target;if(!t.dataset.option)return;options[kind][t.dataset.option]=t.type==='checkbox'?t.checked:Number(t.value);const out=$('#out-'+t.dataset.option);if(out)out.textContent=t.value+({solar:' kW',battery:' kWh',approval:' min',parts:' min'}[t.dataset.option]||'');render();};
}
function setup(){stop();selected=zones[kind][0][0];readings=null;showComparison=false;minute=120;hour=12;const m=meta[kind];location.hash=kind;$$('[data-sector]').forEach(b=>{const active=b.dataset.sector===kind;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});$('#spaceTitle').textContent=m.title;$('#chapter').textContent=m.chapter;$('#scenarioIntro').textContent=m.intro;$('#prompt').textContent=m.prompt;$('#experiment').textContent=m.experiment;$('#storyTitle').textContent=m.story;$('#storyCopy').textContent=m.copy;$('#contextLink').href=m.link;$('#contextLink').textContent=kind==='grocery'?'Open The Kitchen Machine ↗':'Explore the real-world context ↗';$('#modelNote').textContent=m.note;$('#nextAction').textContent=m.next;
 $('#time').min=0;$('#time').max=kind==='winger'?540:23;$('#time').step=kind==='winger'?5:1;$('#timeTicks').innerHTML=(kind==='winger'?['08:00','11:00','14:00','17:00']:['00:00','06:00','12:00','18:00','23:00']).map(t=>`<span>${t}</span>`).join('');$('#zoneButtons').innerHTML=zones[kind].map(([id,n])=>`<button data-zone="${id}" aria-pressed="false">${n}</button>`).join('');buildControls();render();
}
const zoneCopy={inspect:'One example inspection station feeds the service queue. The inspection is a separate stage from final checks.',bay1:'A service bay takes the next ready vehicle. Approval and parts holds happen in a separate waiting area.',bay2:'A service bay takes the next ready vehicle. Skills, tools and technician breaks would be added in a calibrated model.',bay3:'The third service bay can be taken offline to explore the effect on the queue.',quality:'A final-check station verifies completed work before handover. It handles one vehicle at a time in this example.',parts:'Vehicles wait here for a simulated approval or parts delay. Winger’s real Trade Parts Centre is across the road; this is a holding area, not its actual parts location.',lounge:'The customer-facing view can explain a service stage and prepare a clear adviser update. No customers are being tracked.',arrival:'Arriving vehicles and vehicles waiting for the next available station appear in this example holding area.',living:'A sample electrical load for living-area equipment and space heating. No room temperature or thermal model is being inferred.',kitchen:'Kitchen base load, cooking and hot water. Flexible hot-water use can move to midday in this example.',bedrooms:'A sample background load and occupied evening lighting. A real twin would map actual circuits and room sensors.',garage:'The sample EV uses 3.6 kW for two hours. Shifting its charging time changes when energy is needed, not the amount.',solar:'A synthetic sunlight curve drives generation. Real yield depends on location, roof orientation, shading and system design.',battery:'Energy left in the battery at the end of the selected hour. The day starts empty, with charging and discharge limits.',plant:'A fixed essential-services load stays on. A real project needs a site-approved list of systems that must keep running.',cold:'Chilled and frozen equipment stays on. The busy-day switch adds a sample door-opening load; it is not a measured refrigeration model.'};
function compute(){if(kind==='winger')return workshop(options.winger);return energyDay(kind,options[kind]);}
function render(){
 if(readings)readings.forEach(r=>r.stale=Date.now()-r.timestamp>900000);
 const result=compute(),o=options[kind],current=kind==='winger'?null:result.hours[hour],name=zones[kind].find(z=>z[0]===selected)?.[1]||selected;
 $('#time').value=kind==='winger'?minute:hour;$('#timeOutput').textContent=kind==='winger'?clock(minute):hclock(hour);$('#dataMode').textContent=readings?'IMPORTED SNAPSHOT / NOT LIVE':'SIMULATED / NO LIVE CONNECTION';$('#timeLabel').textContent=readings?'MODEL CLOCK / SNAPSHOT IS FIXED':'PLAY THE DAY FORWARD';
 let reading,sub,values={};
 if(kind==='winger'){
  const active=result.jobs.filter(j=>jobState(j,minute)===selected),unavailable=selected.startsWith('bay')&&Number(selected.slice(3))>result.bays;
  reading=unavailable?'Offline':selected==='lounge'?'Adviser view':active.length?active.map(j=>j.id).join(' · '):'Available';sub=active.length?active.length+' synthetic vehicle'+(active.length===1?'':'s')+' at this stage.':'At '+clock(minute)+' in the example day.';
  values=Object.fromEntries(zones.winger.map(([id])=>[id,result.jobs.filter(j=>jobState(j,minute)===id).length]));
  const completed=result.jobs.filter(j=>j.finish<=minute).length;metrics([['HANDOVERS BY 17:00',result.finished+' / '+result.jobs.length,'Synthetic jobs completed within the demo day'],['MEAN TOTAL WAIT',Math.round(result.meanWait)+' <small>min</small>','Includes queue, approval and parts waits'],['AT THIS MOMENT',completed+' <small>complete</small>','Clock: '+clock(minute)+' · sample vehicles'],['LAST HANDOVER',clock(result.lastFinish),'A computed schedule, not a promised time']]);renderWorkshop(result);
 }else{
  values=readings?Object.fromEntries(readings.map(r=>[r.id,r.power])):current.z;
  if(selected==='solar'){reading=readings?'Not imported':fmt(current.pv)+' <small>kW</small>';sub=readings?'The CSV schema covers load zones only.':'Synthetic solar generation during this hour.';}
  else if(selected==='battery'){reading=readings?'Not imported':fmt(current.stored)+' <small>kWh</small>';sub=readings?'Battery state needs its own verified data source.':'Stored at hour end · '+o.battery+' kWh usable capacity.';}
  else{reading=fmt(values[selected]||0)+' <small>kW</small>';sub=readings?'Imported electrical power snapshot.':'Example electrical power during this hour.';}
  if(readings){const total=readings.reduce((n,r)=>n+r.power,0),stale=readings.filter(r=>r.stale).length;metrics([['IMPORTED LOAD',fmt(total)+' <small>kW</small>','Sum of the imported load-zone readings'],['MAPPED ZONES',readings.length,'All required load zones supplied'],['STALE READINGS',stale,'Older than 15 minutes at import'],['CONNECTION','Snapshot','No live feed or equipment control']]);}
  else metrics([['BUILDING LOAD',fmt(current.load)+' <small>kW</small>','Demand during the selected hour'],['SOLAR GENERATION',fmt(current.pv)+' <small>kW</small>','Synthetic daylight × installed capacity'],['GRID IMPORT',fmt(current.imported)+' <small>kW</small>',current.exported>0?'Exporting '+fmt(current.exported)+' kW':'After solar and battery dispatch'],['DAILY GRID IMPORT',fmt(result.imports)+' <small>kWh</small>','Sum across this illustrative 24-hour day']]);renderEnergy(result);
 }
 $('#zoneInfo').innerHTML=`<h3>${name}</h3><div class="reading">${reading}</div><p>${sub}</p><p style="margin-top:16px">${zoneCopy[selected]||'A named area with sample electrical demand. Compare occupied and unoccupied hours, then map it to real meters and building assets.'}</p>`;
 const rr=readings?.find(r=>r.id===selected);$('#sensorStatus').textContent=rr?(rr.stale?'Stale snapshot · ':'Imported snapshot · ')+new Date(rr.timestamp).toLocaleString('en-NZ',{timeZone:'Pacific/Auckland'}):readings?'No reading imported for this asset':'Example status · scenario clock';
 $$('[data-zone]').forEach(b=>{b.classList.toggle('active',b.dataset.zone===selected);b.setAttribute('aria-pressed',b.dataset.zone===selected);});
 $('#comparison').hidden=!showComparison;if(showComparison)compare(result);
 scene?.set({kind,result,minute,hour,values,solar:o.solar||0,battery:o.battery||0,solarOutput:readings?0:current?.pv||0,imported:!!readings});scene?.select(selected);
}
function metrics(items){$('#metrics').innerHTML=items.map(([title,value,note])=>`<div class="metric"><span class="eyebrow">${title}</span><strong>${value}</strong><p>${note}</p></div>`).join('');}
function renderWorkshop(result){$('#chartTitle').textContent='The day, vehicle by vehicle.';const end=Math.max(540,result.lastFinish);$('#chart').innerHTML=`<div class="legend"><span><i style="background:#9baebd"></i>Inspection</span><span><i style="background:#c29aae"></i>Service</span><span><i style="background:#819b84"></i>Final check</span><span>Gaps after arrival show waiting · track ends ${clock(end)}</span></div><div class="job-chart">`+result.jobs.map(j=>`<div class="job-row"><span>${j.id}</span><div class="track" aria-label="${j.id}, arrival ${clock(j.arrival)}, service ${clock(j.serviceStart)} to ${clock(j.serviceEnd)}, completed ${clock(j.finish)}, total wait ${Math.round(j.wait)} minutes">`+[[j.inspectStart,j.inspectEnd,'#9baebd'],[j.serviceStart,j.serviceEnd,'#c29aae'],[j.checkStart,j.finish,'#819b84']].map(([start,finish,c])=>`<span class="segment" style="left:${start/end*100}%;width:${(finish-start)/end*100}%;background:${c}"></span>`).join('')+'</div></div>').join('')+`</div><div class="chart-axis"><span>08:00</span><span>${clock(end/2)}</span><span>${clock(end)}</span></div>`;}
function renderEnergy(result){$('#chartTitle').textContent=readings?'Example-day forecast · separate from your snapshot':'Where the day draws its power.';const max=Math.max(...result.hours.flatMap(h=>[h.load,h.pv]),1);$('#chart').innerHTML=`<div class="legend"><span><i style="background:#b994aa"></i>Building load</span><span><i style="background:#9bb29a"></i>Solar generation</span><span>Scale: 0–${Math.ceil(max)} kW · one-hour intervals</span></div><div class="energy-chart">`+result.hours.map(h=>`<div class="energy-hour ${h.h===hour?'active':''}" aria-label="${hclock(h.h)}: load ${fmt(h.load)} kW, solar ${fmt(h.pv)} kW, grid import ${fmt(h.imported)} kW"><span style="height:${h.load/max*100}%;background:#b994aa"></span><span style="height:${h.pv/max*100}%;background:#9bb29a"></span></div>`).join('')+`</div><div class="chart-axis"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span><span>23:00</span></div><p class="tiny">${readings?'Imported readings colour the spatial view and its metrics. This chart remains the independent example-day model; it is not a forecast derived from the snapshot.':'These are power values (kW). Each bar is one hour, so summing the values gives daily energy (kWh).'}</p>`;}
function compare(r){const base=kind==='winger'?workshop(defaults.winger):energyDay(kind,{...defaults[kind],solar:0,battery:0,smart:false});let rows,copy;
 if(kind==='winger'){rows=[['Service bays','3',options.winger.bays],['Bookings','10',r.jobs.length],['Mean total wait',Math.round(base.meanWait)+' min',Math.round(r.meanWait)+' min'],['Handovers by 17:00',base.finished,r.finished]];copy='Baseline: three bays, ten jobs, 25-minute approval wait, no extra parts delay. Compare the same booking count to isolate capacity or waiting effects.';}
 else{rows=[['Daily consumption',fmt(base.consumption)+' kWh',fmt(r.consumption)+' kWh'],['Grid imports',fmt(base.imports)+' kWh',fmt(r.imports)+' kWh'],['Solar generation','0 kWh',fmt(r.generation)+' kWh'],['Grid exports','0 kWh',fmt(r.exports)+' kWh']];copy='Baseline: occupied day, no solar or battery, and no flexible-load timing or after-hours zoning. This is a scenario comparison, not measured savings. It includes every changed assumption.';}
 $('#comparison').innerHTML='<h3>Baseline → your scenario</h3><p>'+copy+'</p><table><thead><tr><th>Measure</th><th>Baseline</th><th>Your scenario</th></tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map((v,i)=>`<${i?'td':'th'}>${v}</${i?'td':'th'}>`).join('')+'</tr>').join('')+'</tbody></table>';
}
function stop(){clearInterval(playing);playing=null;$('#play').textContent='▶';$('#play').setAttribute('aria-label','Play simulated day');}
function select(id){if(zones[kind].some(z=>z[0]===id)){selected=id;render();}}
function download(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}
function prepare(pilot=false){const r=compute(),n=zones[kind].find(z=>z[0]===selected)[1];const lines=[pilot?'assembl / proposed spatial-twin pilot':'assembl / spatial review brief',meta[kind].title,'Status: DRAFT. No action has been sent or executed.','', 'Selected area: '+n,'Model inputs: '+JSON.stringify(options[kind]),kind==='winger'?`Synthetic day: ${r.jobs.length} jobs; ${r.finished} handovers by 17:00; mean total wait ${Math.round(r.meanWait)} minutes.`:`Example day: ${fmt(r.consumption)} kWh consumption; ${fmt(r.imports)} kWh grid imports; ${fmt(r.generation)} kWh solar generation.`,readings?'Imported snapshot: '+readings.length+' mapped load zones. Snapshot is independent of the example-day forecast.':'Data source: synthetic demonstration.','', 'Proposed next step:',meta[kind].next,'','Before a real pilot:','1. Obtain permissioned floor plans and verify dimensions, rooms, bays and assets.','2. Map read-only data sources and timestamps to asset IDs.','3. Compare model outputs with observed operation; document uncertainty.','4. Agree the human reviewer and the measurable outcome.','5. Keep any future write actions behind explicit approval.','',kind==='winger'?'Needed from Winger: approved Penrose plan, bay capabilities, anonymised job-stage timestamps, parts/approval events and service-adviser workflow.':'Needed: building plan, asset/circuit register, interval meter readings, occupancy schedule, tariffs if cost is later modelled, and equipment/control permissions.','',meta[kind].note,'Reviewer: __________________','Decision / notes: __________________'];$('#briefTitle').textContent=pilot?'A pilot worth reviewing.':'Your next step, prepared.';$('#briefText').value=lines.filter(x=>x!==undefined).join('\n');$('#briefDialog').showModal();}
$$('[data-sector]').forEach(b=>b.onclick=()=>{kind=b.dataset.sector;setup();});$('#zoneButtons').onclick=e=>{const b=e.target.closest('[data-zone]');if(b)select(b.dataset.zone);};$('#reset').onclick=()=>{options[kind]=structuredClone(defaults[kind]);setup();notice('Example scenario restored.');};$('#experiment').onclick=()=>{if(kind==='winger')options.winger.bays=2;else if(kind==='home'){options.home.smart=true;options.home.solar=6;options.home.battery=5;hour=12;}else{options[kind].occupied=false;options[kind].smart=true;hour=19;}showComparison=true;buildControls();render();};$('#compare').onclick=()=>{showComparison=!showComparison;render();if(showComparison)$('#comparison').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});};$('#time').oninput=e=>{stop();if(kind==='winger')minute=Number(e.target.value);else hour=Number(e.target.value);render();};$('#play').onclick=()=>{if(playing){stop();return;}$('#play').textContent='Ⅱ';$('#play').setAttribute('aria-label','Pause simulated day');playing=setInterval(()=>{if(kind==='winger')minute=minute>=540?0:minute+15;else hour=(hour+1)%24;render();},900);};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
$$('[data-camera]').forEach(b=>b.onclick=()=>{$$('[data-camera]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});scene?.view(b.dataset.camera);});$('#roof').onclick=()=>{roof=!roof;$('#roof').setAttribute('aria-pressed',roof);scene?.roof(roof);};$('#labels').onclick=()=>{labels=!labels;$('#labels').setAttribute('aria-pressed',labels);scene?.labels(labels);};$('#zoomIn').onclick=()=>scene?.zoom(1);$('#zoomOut').onclick=()=>scene?.zoom(-1);$('#resetView').onclick=()=>scene?.reset();$('#brief').onclick=()=>prepare();$('#pilotButton').onclick=()=>prepare(true);$$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#copyBrief').onclick=async()=>{try{await navigator.clipboard.writeText($('#briefText').value);notice('Draft copied. Nothing has been sent.');}catch{notice('Select the brief text to copy it, or download it.');}};$('#downloadBrief').onclick=()=>download('assembl-'+kind+'-review.txt',$('#briefText').value);
$('#dataButton').onclick=()=>{if(kind==='winger'){notice('Workshop data needs job-stage events. The pilot brief lists the required fields.');prepare(true);return;}$('#mapping').textContent='zone_id,power_kw,timestamp\n'+zones[kind].filter(([id])=>!['solar','battery'].includes(id)).map(([id])=>id+',0.5,2026-10-23T12:00:00+13:00').join('\n');$('#importStatus').textContent=readings?'A snapshot is loaded in this tab.':'No readings imported.';$('#dataDialog').showModal();};$('#template').onclick=()=>{const day=energyDay(kind,options[kind]),timestamp=new Date().toISOString();download('assembl-'+kind+'-SAMPLE-readings.csv','zone_id,power_kw,timestamp\n'+Object.entries(day.hours[hour].z).map(([id,p])=>[id,p,timestamp].join(',')).join('\n'),'text/csv');notice('Template contains example values. Replace them with authorised measurements.');};$('#sensorFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>100000)throw Error('Use a CSV under 100 KB.');readings=parseReadings(await f.text(),kind);$('#importStatus').textContent='Snapshot loaded. '+readings.filter(r=>r.stale).length+' readings are stale. The forecast remains an example.';render();}catch(err){$('#importStatus').textContent=err.message;}e.target.value='';};$('#clearReadings').onclick=()=>{readings=null;$('#importStatus').textContent='Example readings restored.';render();};
$('#planFile').onchange=e=>{const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>10*1024*1024){notice('Choose a PNG, JPG or WebP under 10 MB.');return;}if(planURL)URL.revokeObjectURL(planURL);planURL=URL.createObjectURL(f);$('#planPreview img').src=planURL;$('#planPreview').hidden=false;notice('Reference added locally. The example 3D geometry is unchanged.');};$('#removePlan').onclick=()=>{if(planURL)URL.revokeObjectURL(planURL);planURL=null;$('#planPreview').hidden=true;$('#planPreview img').removeAttribute('src');$('#planFile').value='';};
setup();import('./twin-scene.js').then(m=>{scene=m.initTwin($('#twinScene'),select);render();}).catch(()=>{$('#twinScene').innerHTML='<div class="loading">3D could not load. Area buttons and all model controls remain available.</div>';});

$('#applyCSV').onclick=()=>{try{readings=parseReadings($('#pasteCSV').value,kind);$('#importStatus').textContent='Snapshot loaded. '+readings.filter(r=>r.stale).length+' readings are stale. The forecast remains an example.';render();}catch(err){$('#importStatus').textContent=err.message;}};
